// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address nonOwner, uint256 amount) public {
        vm.assume(nonOwner != address(this));
        amount = bound(amount, 1, type(uint128).max);
        vm.deal(address(c), amount);
        uint256 balBefore = address(c).balance;
        bool ok;
        vm.prank(nonOwner);
        try c.withdrawAll(nonOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok || address(c).balance == balBefore);
    }
}
